package io.github.miklires.mclans.clan;
import static org.junit.jupiter.api.Assertions.assertEquals;import java.util.List;import java.util.Set;import org.junit.jupiter.api.Test;
class ClanRulesTest {@Test void validatesNamesAndReservedWords(){var p=new ClanNamingPolicy("[A-Za-z0-9_]{3,16}","[A-Za-z0-9]{2,5}",Set.of("admin"));assertEquals(ClanNamingPolicy.Result.ALLOWED,p.validate("Knights","KNG"));assertEquals(ClanNamingPolicy.Result.RESERVED,p.validate("Admin","ADM"));assertEquals(ClanNamingPolicy.Result.BAD_TAG,p.validate("Knights","!"));}@Test void riskyRegexFallsBackToSafeNaming(){var p=new ClanNamingPolicy("(a+)+","(b+)+",Set.of());assertEquals(ClanNamingPolicy.Result.ALLOWED,p.validate("Knights","KNG"));}@Test void resolvesLevelFromPoints(){var p=new ClanProgression(List.of(new ClanProgression.Level(1,0,5),new ClanProgression.Level(2,100,8),new ClanProgression.Level(3,500,12)));assertEquals(1,p.forPoints(99).level());assertEquals(2,p.forPoints(499).level());assertEquals(3,p.forPoints(500).level());} @Test void rejectsBrokenProgression(){org.junit.jupiter.api.Assertions.assertThrows(IllegalArgumentException.class,()->new ClanProgression(List.of(new ClanProgression.Level(1,0,5),new ClanProgression.Level(3,100,8))));}}
